import{_ as a,o as e,c as n,a as s}from"./app-af0774fa.js";const t={},i=s(`<p>Netstat 是一款命令行工具，可用于列出系统上所有的网络套接字连接情况，包括 tcp, udp 以及 unix 套接字，另外它还能列出处于监听状态（即等待接入请求）的套接字。</p><h1 id="安装" tabindex="-1"><a class="header-anchor" href="#安装" aria-hidden="true">#</a> 安装</h1><p>CentOS 7没有netstat命令，需要安装:</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>yum <span class="token function">install</span> net-tools
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h1 id="常见参数" tabindex="-1"><a class="header-anchor" href="#常见参数" aria-hidden="true">#</a> 常见参数</h1><ul><li>-a(all) 显示所有选项，默认不显示LISTEN相关</li><li>-t(tcp) 仅显示tcp相关选项</li><li>-u(udp) 仅显示udp相关选项</li><li>-n 拒绝显示别名，能显示数字的全部转化成数字</li><li>-l 仅列出又在LISTEN（监听）的服务状态</li><li>-p 显示建立相关链接的程序名</li><li>-r 显示路由信息，路由表</li><li>-e 显示扩展信息，例如uid等</li><li>-s 按各个协议进行统计</li><li>-c 每隔一个固定时间，执行netstat命令</li></ul><h2 id="禁用反向域名解析-加快查询速度" tabindex="-1"><a class="header-anchor" href="#禁用反向域名解析-加快查询速度" aria-hidden="true">#</a> 禁用反向域名解析，加快查询速度</h2><p>默认情况下netstat 会通过反向域名解析技术查找每个IP地址对应的主机名，会大幅降低查找速度。如果没有必要知道主机名，就使用 -n 选项禁用域名解析功能。</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">netstat</span> <span class="token parameter variable">-ant</span> <span class="token comment">###显示所有非别名tcp相关选项</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="只列出监听中的连接" tabindex="-1"><a class="header-anchor" href="#只列出监听中的连接" aria-hidden="true">#</a> 只列出监听中的连接</h2><p>任何网络服务的后台进程都会打开一个端口，用于监听接入的请求。使用 -l 选项列出正在监听的套接字。</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">netstat</span> <span class="token parameter variable">-tnl</span> <span class="token comment">###显示正在监听的非别名地址端口</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="显示进程名-进程号以及用户id" tabindex="-1"><a class="header-anchor" href="#显示进程名-进程号以及用户id" aria-hidden="true">#</a> 显示进程名，进程号以及用户ID</h2><p>可以通过netstat查看网络端口被哪些进程占用</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">netstat</span> <span class="token parameter variable">-tnlp</span> <span class="token comment">###显示正在监听的非别名端口使用的进程id及进程名</span>
<span class="token function">netstat</span> <span class="token parameter variable">-tlep</span> <span class="token comment">###显示正在监听的别名（域名）端口使用的进程id及进程名和用户名</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>::: tips 使用 -p 选项时，netstat必须运行在root权限，使用 -ep选项可以同时查看进程名和用户名。 :::</p><h2 id="打印统计数据-路由信息-网络接口" tabindex="-1"><a class="header-anchor" href="#打印统计数据-路由信息-网络接口" aria-hidden="true">#</a> 打印统计数据 路由信息 网络接口</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">netstat</span> <span class="token parameter variable">-su</span> <span class="token comment">###打印出网络统计数据</span>
<span class="token function">netstat</span> <span class="token parameter variable">-ru</span> <span class="token comment">###内核IP路由表</span>
<span class="token function">netstat</span> <span class="token parameter variable">-ie</span> <span class="token comment">###打印网络接口等同于ifconfig</span>
<span class="token function">netstat</span> <span class="token parameter variable">-g</span> <span class="token comment">###输出IPv4和IPv6的多播组信息</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="查看服务是否在运行" tabindex="-1"><a class="header-anchor" href="#查看服务是否在运行" aria-hidden="true">#</a> 查看服务是否在运行</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">netstat</span> <span class="token parameter variable">-aple</span> <span class="token operator">|</span> <span class="token function">grep</span> http
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div>`,20),l=[i];function d(r,c){return e(),n("div",null,l)}const o=a(t,[["render",d],["__file","CentOS netguanligongju.html.vue"]]);export{o as default};
